&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&amp;nbsp;&lt;u style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Census 2011 highlights:&lt;/span&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;India&amp;rsquo;s population growth rate is 17.64 percent in the decade 2001-11, &lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;The slowest rate of growth this past century, as per data put out by the registrar-general of the census.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;India&amp;rsquo;s population in 2011 is estimated to be 1.21 billion,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;comprising 624 million males and 587 million females.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;While the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;gender imbalance in the population remains.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;India&amp;rsquo;s&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;female population grew by 18.12%&lt;/span&gt;&amp;nbsp;over the past decade against&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;17.19%&amp;nbsp;for males.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;India&amp;rsquo;s li&lt;span style=&quot;font-weight: 700;&quot;&gt;teracy rate has gone up from 64.83% in 2001 to 74.04% in 2011.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Literates constitute 74 percent of the total population&amp;nbsp;&lt;/span&gt;aged seven and above.&lt;/li&gt;
		&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;sex ratio,&lt;/span&gt;&amp;nbsp;that is the number of females per 1,000 males, has&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;improved to 940 from 933 a decade ago.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;The child sex ratio is 914, the lowest since independence.&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;The&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;first synchronous census&lt;/span&gt;&amp;nbsp;was taken under British rule on&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;February 17, 1881, by&amp;nbsp;W.C.&amp;nbsp;Plowden&amp;nbsp;&lt;/span&gt;(Census Commissioner of India).&lt;/li&gt;
	&lt;li&gt;It has been&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;conducted by&amp;nbsp;the Registrar General and Census Commissioner&amp;nbsp;&lt;/span&gt;of India.&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Shri Vivek Joshi&amp;nbsp;&lt;/span&gt;is the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;present&amp;nbsp;Registrar General and Census Commissioner, Ministry of Home Affairs.&lt;/span&gt;&lt;/li&gt;
