&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जनगणना 2011 की मुख्य बातें:&lt;/span&gt;&lt;/u&gt; &lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;2001-11 के दशक में भारत की जनसंख्या वृद्धि दर 17.64 प्रतिशत है।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जनगणना के रजिस्ट्रार-जनरल द्वारा जारी आंकड़ों के अनुसार, यह पिछली सदी में सबसे धीमी विकास दर है।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;2011 में भारत की जनसंख्या 1.21 अरब होने का अनुमान है, &lt;span style=&quot;font-weight: 700;&quot;&gt;जिसमें 624 मिलियन पुरुष और 587 मिलियन महिलाएँ शामिल हैं।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;जबकि &lt;span style=&quot;font-weight: 700;&quot;&gt;जनसंख्या में लैंगिक असंतुलन बना हुआ है।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;भारत कापिछले दशक में &lt;span style=&quot;font-weight: 700;&quot;&gt;पुरुषों की 17.19%&lt;/span&gt; की तुलना में &lt;span style=&quot;font-weight: 700;&quot;&gt;महिला जनसंख्या में 18.12% की वृद्धि हुई&lt;/span&gt; ।&lt;/li&gt;
		&lt;li&gt;भारत की &lt;span style=&quot;font-weight: 700;&quot;&gt;साक्षरता दर 2001 में 64.83% से बढ़कर 2011 में 74.04% हो गई है।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;सात वर्ष और उससे अधिक उम्र की &lt;span style=&quot;font-weight: 700;&quot;&gt;कुल आबादी का 74 प्रतिशत साक्षर हैं&lt;/span&gt; ।&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;लिंगानुपात,&lt;/span&gt;&amp;nbsp;अर्थात प्रति 1,000 पुरुषों पर महिलाओं की संख्या, &lt;span style=&quot;font-weight: 700;&quot;&gt;एक दशक पहले के 933 से बढ़कर 940 हो गई है।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;बाल लिंगानुपात 914 है, जो आज़ादी &lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;के&lt;/span&gt;&lt;/span&gt; बाद से सबसे कम है।&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;ब्रिटिश शासन के तहत &lt;span style=&quot;font-weight: 700;&quot;&gt;पहली समकालिक जनगणना&lt;/span&gt; &lt;span style=&quot;font-weight: 700;&quot;&gt;17 फरवरी, 1881 को डब्ल्यूसी प्लॉडेन (भारत के जनगणना आयुक्त) द्वारा&lt;/span&gt; की गई थी।&lt;/li&gt;
	&lt;li&gt;इसका &lt;span style=&quot;font-weight: 700;&quot;&gt;संचालन भारत के रजिस्ट्रार जनरल और जनगणना आयुक्त द्वारा किया गया है&lt;/span&gt; ।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;श्री विवेक जोशी&lt;/span&gt; &lt;span style=&quot;font-weight: 700;&quot;&gt;गृह मंत्रालय के वर्तमान रजिस्ट्रार जनरल और जनगणना आयुक्त हैं।&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;दिया है:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;एक लड़का 4 किमी/घण्टा की गति से चल रहा है।&lt;/p&gt;

&lt;p&gt;वह एक वर्गाकार मैदान को तिरछे पार करता है = 36 सेकंड&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;प्रयुक्त सूत्र:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;वर्ग का विकर्ण = a&amp;radic;2&lt;/p&gt;

&lt;p&gt;वर्ग का क्षेत्रफल = a&lt;sup&gt;2&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;एक लड़का 36 सेकंड में पार करता है = (4&amp;nbsp;&amp;times; 5/18&amp;nbsp;&amp;times; 36)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 40 मीटर&lt;/p&gt;

&lt;p&gt;माना वर्ग की प्रत्येक भुजा का माप L है।&lt;/p&gt;

&lt;p&gt;प्रश्नानुसार&lt;/p&gt;

&lt;p&gt;&amp;rArr; L&amp;radic;2 = 40&lt;/p&gt;

&lt;p&gt;&amp;rArr; L = 20&amp;radic;2&lt;/p&gt;

&lt;p&gt;अब,&lt;/p&gt;

&lt;p&gt;मैदान का&amp;nbsp;क्षेत्रफल = (20&amp;radic;2)&lt;sup&gt;2&lt;/sup&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; (400&amp;nbsp;&amp;times; 2)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 800 मीटर&lt;sup&gt;2&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; अभीष्ट क्षेत्रफल 800 मीटर&lt;/strong&gt;&lt;strong&gt;&lt;sup&gt;2&lt;/sup&gt; है।&lt;/strong&gt;&lt;/p&gt;

