&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&lt;strong&gt;= 18 + 10 = 28.&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;विकल्प 3:&lt;/span&gt;&lt;/strong&gt; &lt;span style=&quot;&quot;&gt;(7, 17, 12)&lt;/span&gt;&lt;/p&gt;

