&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 2x + 3y = 650&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;Multiply 2 on both sides&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;4x + 6y = 1300&amp;nbsp;&lt;/strong&gt; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; -----(1)&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;T&lt;/span&gt;&lt;span style=&quot;&quot;&gt;he cost of 4 pairs of pants and 2 shirts is Rs.700&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;4x + 2y = 700&amp;nbsp; &amp;nbsp; &lt;/strong&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;-------(2)&lt;/p&gt;

&lt;p&gt;Doing equation (2) - (1)&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;(4x + 6y) - (4x + 2y) = 1300 - 700&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;4y = 600&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;y = 150&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; The cost of each shirt is Rs. 150&lt;/strong&gt;&lt;/p&gt;

