&lt;p style=&quot;color:  (33, 37, 41);&quot;&gt;&lt;span style=&quot;font-weight: bolder;&quot;&gt;So, checking all options:&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;table border=&quot;1&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot;color:  (33, 37, 41); width: 500px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
